// GraphQL schema definition for volunteer management
// This file defines the GraphQL types, queries, and mutations for volunteer operations

/**
 * GraphQL type definitions for volunteer-related operations.
 * 
 * This schema defines:
 * - Volunteer type: represents a volunteer record with all fields
 * - VolunteerInput type: input for creating new volunteers (excludes auto-generated ID)
 * - Query operations: fetch volunteers individually or as a list
 * - Mutation operations: create new volunteer records
 * 
 * The schema uses GraphQL SDL (Schema Definition Language) syntax.
 */
export const volunteerTypeDefs = `
  # Custom scalar for handling date/time values
  # This allows GraphQL to properly serialize/deserialize JavaScript Date objects
  scalar DateTime
  
  # Main Volunteer type representing a volunteer record in the database
  # All fields marked with ! are non-nullable (required)
  type Volunteer {
    volunteer_id: ID!           # Unique identifier (UUID)
    first_name: String!         # Volunteer's first name
    last_name: String!          # Volunteer's last name  
    email: String!              # Contact email address
    graduation_date: DateTime!  # When they graduated (for students/recent grads)
    volunteer_status: String!   # Current status (active, inactive, etc.)
    volunteer_type: String!     # Type of volunteer role
    university_id: String!      # ID of associated university
  }

  # Input type for creating new volunteers
  # Excludes volunteer_id since that's auto-generated by the database
  input VolunteerInput {
    first_name: String!         # Required: volunteer's first name
    last_name: String!          # Required: volunteer's last name
    email: String!              # Required: contact email
    graduation_date: DateTime!  # Required: graduation date
    volunteer_status: String!   # Required: initial status
    volunteer_type: String!     # Required: volunteer role type
    university_id: String!      # Required: associated university
  }
 
  # Query operations for reading volunteer data
  type Query {
    # Get all volunteers - returns non-null array of non-null volunteers
    volunteers: [Volunteer!]!
    
    # Get single volunteer by ID - returns volunteer or null if not found  
    volunteer(id: ID!): Volunteer
  }  

  # Mutation operations for modifying volunteer data
  type Mutation {
    # Create a new volunteer record
    # Takes required input object, returns the created volunteer
    createVolunteer(input: VolunteerInput!): Volunteer!
  }
`;
